<?php
declare(strict_types=1);
$op=$argv[1]??''; $worker=$argv[2]??'worker'; $barrier=$argv[3]??''; $transfer=(int)($argv[4]??0); $staff=(int)($argv[5]??0); $destination=(string)($argv[6]??'PKM-DEST');
if(!in_array($op,['schedule','activate','semantic'],true)||getenv('GOVERNANCE_WORKER_READY')!=='true'||$barrier===''){echo "WORKER_RESULT=BLOCKED\nWORKER_REASON=runtime_context_missing\n";exit(2);}
define('BASEPATH','/var/www/html/system/'); define('APPPATH','/var/www/html/application/'); define('FCPATH','/var/www/html/'); define('ENVIRONMENT','staging');
require_once BASEPATH.'core/Common.php'; require_once BASEPATH.'database/DB.php';
$db=DB(['dsn'=>'','hostname'=>getenv('DB_HOST'),'username'=>getenv('DB_USER'),'password'=>getenv('DB_PASS'),'database'=>getenv('DB_NAME'),'dbdriver'=>'mysqli','dbprefix'=>'','pconnect'=>false,'db_debug'=>false,'cache_on'=>false,'cachedir'=>'','char_set'=>'utf8','dbcollat'=>'utf8_general_ci','port'=>3306,'stricton'=>false],true);
